const arr = [1, 2, 3];

// Spread: разворачивает массив в отдельные значения
console.log(...arr);  // 1 2 3 — каждый элемент отдельно

// Math.max ждёт отдельные аргументы, а не массив
// Math.max(arr) — не работает, а Math.max(...arr) — да
console.log(Math.max(...arr));  // 3

// Объединение массивов:
const combined = [...arr, 4, 5];
console.log(combined);  // [1, 2, 3, 4, 5]

const original = [1, 2, 3];
const copy = [...original];  // новый массив с теми же элементами

copy.push(4);  // меняем только копию
console.log(original);  // [1, 2, 3] — оригинал не изменился!
console.log(copy);      // [1, 2, 3, 4] — изменённая копия

// Без spread (через ссылку) — обе переменные указывают на один массив:
const bad = original;
bad.push(99);
console.log(original);  // [1, 2, 3, 99] — оригинал ИЗМЕНИЛСЯ!

const user = { name: "Alice", age: 25 };

// Копия объекта с изменением одного свойства:
const updated = { ...user, age: 26 };
console.log(updated);  // { name: "Alice", age: 26 }
console.log(user);     // { name: "Alice", age: 25 } — оригинал цел

// Объединение объектов:
const defaults = { theme: "dark", lang: "ru" };
const userPrefs = { theme: "light" };
const settings = { ...defaults, ...userPrefs };
console.log(settings);  // { theme: "light", lang: "ru" }

