// Rest: собирает все аргументы в массив
function sumAll(...nums) {
  // nums — массив: [1, 2, 3]
  return nums.reduce((acc, n) => acc + n, 0);
}

console.log(sumAll(1, 2, 3));      // 6
console.log(sumAll(10, 20, 30, 40)); // 100

// Rest в деструктуризации:
const [first, ...rest] = [1, 2, 3, 4];
console.log(first);  // 1
console.log(rest);   // [2, 3, 4] — остальные элементы

const user = {
  name: "Alice",
  address: { city: "Moscow" }  // вложенный объект
};

// Поверхностная копия:
const copy = { ...user };
copy.name = "Bob";         // меняем верхний уровень — безопасно
copy.address.city = "SPb"; // меняем вложенный — ОПАСНО!

console.log(user.address.city);  // "SPb" — оригинал ИЗМЕНИЛСЯ!
// Потому что copy.address и user.address — одна и та же ссылка

// Глубокая копия:
const deep = JSON.parse(JSON.stringify(user));
deep.address.city = "Kazan";
console.log(user.address.city);  // "SPb" — оригинал цел

const user = { name: "Alice", age: 25, city: "Moscow", email: "a@b.com" };

// Достаём name, а всё остальное собираем в other
const { name, ...other } = user;
console.log(name);   // Alice
console.log(other);  // { age: 25, city: "Moscow", email: "a@b.com" }

// Удаление поля без мутации:
const { email, ...withoutEmail } = user;
console.log(withoutEmail);  // { name: "Alice", age: 25, city: "Moscow" }

function add(a, b, c) {
  return a + b + c;
}

const nums = [1, 2, 3];
console.log(add(...nums));  // 6 — add(1, 2, 3)

// Math.max со spread:
console.log(Math.max(...nums));  // 3

// Spread для строк — в массив символов:
console.log([..."hey"]);  // ["h", "e", "y"]

const a = [1, 2, 3];
const b = [4, 5, 6];

// Объединение через spread:
const merged = [...a, ...b];
console.log(merged);  // [1, 2, 3, 4, 5, 6]

// Вставка в середину:
const middle = [10, 20];
const full = [...a, ...middle, ...b];
console.log(full);  // [1, 2, 3, 10, 20, 4, 5, 6]

